import { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { api } from "@/api";
import Md from "@/components/Md";
import { Err, Loading } from "@/components/common";

/** Gold pages (generated by `kb build`, no frontmatter): /gold/390_daily, /gold/304_books/index … */
export default function Gold() {
  const name = decodeURIComponent(useLocation().pathname.replace(/^\/gold\//, "")).replace(/\.md$/, "");
  const [md, setMd] = useState<string | null>(null);
  const [err, setErr] = useState<unknown>(null);
  useEffect(() => {
    setMd(null); setErr(null);
    api.gold(name).then((g) => setMd(g.markdown.replace(/^<!--[\s\S]*?-->\n?/, ""))).catch(setErr);
  }, [name]);
  if (err) return <Err e={err} />;
  if (md === null) return <Loading rows={8} />;
  return (
    <>
      <p className="text-sm text-muted-foreground">300_gold/{name}.md（kb build が生成）</p>
      <Md text={md} basePath={`300_gold/${name}.md`} />
    </>
  );
}
